const { withAndroidColors, withAndroidStyles, AndroidConfig } = require("expo/config-plugins");

const { assignColorValue } = AndroidConfig.Colors;
const { assignStylesValue, getAppThemeGroup } = AndroidConfig.Styles;

/**
 * The window background and the system bars, in the app's own colour.
 *
 * `android/` is gitignored and regenerated by `expo prebuild`, so this belongs
 * in a plugin rather than in the generated files.
 *
 * The status bar is already transparent, which means whatever sits behind it
 * shows through — and that is the window background, which prebuild had set to
 * `splashscreen_background`, white. On a dark app the result was a white strip
 * across the top with the clock and the icons invisible inside it. The same
 * white is what flashes before the first frame renders.
 */
const CANVAS = "#0D0E11";

const withDarkSystemChrome = (config) => {
  let next = withAndroidColors(config, (mod) => {
    mod.modResults = assignColorValue(mod.modResults, {
      name: "splashscreen_background",
      value: CANVAS,
    });
    mod.modResults = assignColorValue(mod.modResults, {
      name: "activityBackground",
      value: CANVAS,
    });
    return mod;
  });

  next = withAndroidStyles(next, (mod) => {
    // Light icons, because everything behind them is dark.
    mod.modResults = assignStylesValue(mod.modResults, {
      add: true,
      name: "android:windowLightStatusBar",
      value: "false",
      parent: getAppThemeGroup(),
    });
    mod.modResults = assignStylesValue(mod.modResults, {
      add: true,
      name: "android:navigationBarColor",
      value: "@android:color/transparent",
      parent: getAppThemeGroup(),
    });
    return mod;
  });

  return next;
};

module.exports = withDarkSystemChrome;
